import { type Row,type DemoState,type OperationContext,DemoError,object,str,num,rows,find,uid,now,quantity,manager,operator,staff,requireActor,portal,financial,addEvent,idempotent } from "./types";
import { resolveDemoPortalSettings } from "./portal-settings";
