export type RpcHandler=(state:DemoState,ctx:OperationContext,p:Row)=>unknown;
export type RpcDefinition={write:boolean;handle:RpcHandler};
export const operationalRpcs:Record<string,RpcDefinition>={};
const register=(names:string[],handle:RpcHandler,write=true)=>names.forEach(name=>{operationalRpcs[name]={write,handle:(s,c,p)=>idempotent(s,c,p.p_operation_id,name,p,()=>handle(s,c,p))};});
function createRow(state:DemoState,table:string,input:Row):Row{const row={id:uid(),is_active:true,created_at:now(),updated_at:now(),...input};rows(state,table).push(row);return row;}
function nonfinancialInput(ctx:OperationContext,input:Row):void{if(!financial(ctx)&&["cost","purchase_cost","unit_cost","invoice_number","invoice_date","unit_price"].some(k=>input[k]!=null))throw new DemoError("42501","financial_access_denied",403);}
function assetMovement(state:DemoState,ctx:OperationContext,asset:Row,patch:Row,type:string,note:unknown=null):void{addEvent(state,ctx,"asset_movements",{asset_id:asset.id,movement_type:type,from_location_id:asset.location_id,to_location_id:patch.location_id??asset.location_id,from_employee_id:asset.assigned_to_employee_id,to_employee_id:Object.hasOwn(patch,"assigned_to_employee_id")?patch.assigned_to_employee_id:asset.assigned_to_employee_id,from_status:asset.status,to_status:patch.status??asset.status,performed_by:ctx.actor?.userId,note});Object.assign(asset,patch,{updated_at:now()});}
export function createAsset(state:DemoState,ctx:OperationContext,input:Row):Row{manager(ctx);nonfinancialInput(ctx,input);input={...input};for(const key of ["id","created_at","updated_at","qr_token","created_by"])delete input[key];validateDemoAssetIntegrity(state,{status:"available",...input,created_by:ctx.actor?.userId});find(state,"categories",input.category_id);if(input.model_id)find(state,"models",input.model_id);if(input.location_id)find(state,"locations",input.location_id);if(input.serial_number&&rows(state,"assets").some(a=>a.serial_number===input.serial_number))throw new DemoError("23505","serial_number_duplicate");const category=find(state,"categories",input.category_id);const tag=input.asset_tag??`${category.prefix}-${String(rows(state,"assets").length+1).padStart(4,"0")}`;if(rows(state,"assets").some(a=>a.asset_tag===tag))throw new DemoError("23505","asset_tag_duplicate");const a=createRow(state,"assets",{qr_token:uid(),asset_tag:tag,name:null,serial_number:null,status:"available",location_id:null,department_id:null,assigned_to_employee_id:null,purchase_cost:null,currency:"SAR",condition_grade:"good",purchase_date:null,warranty_end:null,lifespan_months:36,supplier_id:null,company_id:null,pool_id:null,rfid_tag:null,notes:null,special_attributes:{},archived_at:null,serial_exempt:false,times_checked_out:0,unsound_return_count:0,last_return_condition:null,...input,created_by:ctx.actor?.userId});assetMovement(state,ctx,a,{},"create");return a;}
register(["asset_create_atomic"],(s,c,p)=>({ok:true,id:createAsset(s,c,object(p.p_input)).id}));
register(["asset_update_atomic"],(s,c,p)=>{manager(c);const input=object(p.p_input);nonfinancialInput(c,input);const a=find(s,"assets",p.p_asset_id);validateDemoAssetIntegrity(s,{...a,...input},a);const patch={...input};for(const key of ["id","created_at","updated_at","qr_token"])delete patch[key];if(input.serial_number&&rows(s,"assets").some(other=>other.id!==a.id&&other.serial_number===input.serial_number))throw new DemoError("23505","serial_number_duplicate");assetMovement(s,c,a,patch,"update");return{ok:true};});
register(["asset_assign"],(s,c,p)=>{operator(c);const a=find(s,"assets",p.p_asset_id);const employee=find(s,"employees",p.p_employee_id);if(a.status!=="available"||a.assigned_to_employee_id)throw new DemoError("P0001","asset_not_available");const assignment=createRow(s,"asset_assignments",{asset_id:a.id,employee_id:employee.id,assigned_by:c.actor?.userId,assigned_at:now(),due_return_date:p.p_due_date??null,returned_at:null,status:"active",notes:null});assetMovement(s,c,a,{status:"reserved",assigned_to_employee_id:employee.id,times_checked_out:num(a.times_checked_out)+1},"assign");return{ok:true,id:assignment.id};});
register(["asset_return"],(s,c,p)=>{operator(c);const a=find(s,"assets",p.p_asset_id);if(!a.assigned_to_employee_id)throw new DemoError("P0001","asset_not_assigned");for(const assignment of rows(s,"asset_assignments").filter(x=>x.asset_id===a.id&&x.status==="active"))Object.assign(assignment,{status:"returned",returned_at:now(),return_condition:p.p_condition??"good"});assetMovement(s,c,a,{status:"available",assigned_to_employee_id:null,last_return_condition:p.p_condition??"good",last_return_at:now()},"return");return{ok:true};});
register(["asset_move_atomic","scan_warehouse_move","scan_warehouse_exit"],(s,c,p)=>{operator(c);const a=find(s,"assets",p.p_asset_id);const location=p.p_to_location_id??p.p_destination_id??p.p_location_id??p.p_warehouse_id;if(!location)throw new DemoError("22023","destination_required");find(s,"locations",location);assetMovement(s,c,a,{location_id:location,...(p.p_to_department_id?{department_id:p.p_to_department_id}:{})},"move",p.p_note??p.p_reason);return{ok:true,id:a.id};});
register(["asset_change_status"],(s,c,p)=>{operator(c);const a=find(s,"assets",p.p_asset_id);if(!["available","reserved","in_maintenance"].includes(str(p.p_to_status)))throw new DemoError("22023","invalid_status");if(a.assigned_to_employee_id&&p.p_to_status==="available")throw new DemoError("P0001","active_assignment");assetMovement(s,c,a,{status:p.p_to_status},"status_change");return{ok:true};});
register(["asset_set_serial"],(s,c,p)=>{operator(c);const a=find(s,"assets",p.p_asset_id);if(!str(p.p_serial).trim())throw new DemoError("22023","empty");if(rows(s,"assets").some(x=>x.id!==a.id&&x.serial_number===p.p_serial))throw new DemoError("23505","serial_number_duplicate");a.serial_number=str(p.p_serial).trim();return{ok:true};});
register(["asset_set_serial_exempt"],(s,c,p)=>{manager(c);const a=find(s,"assets",p.p_asset_id);if(p.p_exempt&&!str(p.p_reason).trim())throw new DemoError("22023","reason_required");Object.assign(a,{serial_exempt:p.p_exempt===true,serial_exempt_reason:p.p_exempt?p.p_reason:null});return{ok:true};});
register(["consumable_create_with_opening_stock"],(s,c,p)=>{manager(c);const input=object(p.p_input);nonfinancialInput(c,input);if(!str(input.name).trim())throw new DemoError("22023","name_required");const opening=num(input.quantity_on_hand??input.opening_quantity??input.quantity);if(opening<0||!Number.isInteger(opening))throw new DemoError("22023","invalid_quantity");const item=createRow(s,"consumables",{brand:null,sku:null,category_id:null,company_id:null,supplier_id:null,location_id:null,rfid_tag:null,unit:"piece",reorder_level:10,unit_cost:null,...input,quantity_on_hand:opening});if(opening)createRow(s,"consumable_transactions",{consumable_id:item.id,txn_type:"in",quantity:opening,previous_quantity:0,balance_after:opening,reason:"opening_stock",unit_cost:input.unit_cost??null,total_cost:input.unit_cost==null?null:num(input.unit_cost)*opening,performed_by:c.actor?.userId,location_id:item.location_id});return{ok:true,id:item.id};});
register(["consumable_update_atomic"],(s,c,p)=>{manager(c);const input=object(p.p_input);nonfinancialInput(c,input);if(Object.hasOwn(input,"quantity_on_hand"))throw new DemoError("42501","stock_move_required",403);Object.assign(find(s,"consumables",p.p_consumable_id),input,{updated_at:now()});return{ok:true};});
register(["consumable_stock_move_idempotent"],(s,c,p)=>{operator(c);const item=find(s,"consumables",p.p_consumable_id);const qty=quantity(p.p_quantity);if(!["in","out"].includes(str(p.p_type)))throw new DemoError("22023","invalid_type");nonfinancialInput(c,{unit_cost:p.p_unit_cost,invoice_number:p.p_invoice_number});const prev=num(item.quantity_on_hand);const next=prev+(p.p_type==="in"?qty:-qty);if(next<0)throw new DemoError("P0001","insufficient_stock");item.quantity_on_hand=next;const tx=createRow(s,"consumable_transactions",{consumable_id:item.id,txn_type:p.p_type,quantity:qty,previous_quantity:prev,balance_after:next,reason:p.p_reason??null,performed_by:c.actor?.userId,unit_cost:p.p_unit_cost??null,total_cost:p.p_unit_cost==null?null:qty*num(p.p_unit_cost),invoice_number:p.p_invoice_number??null,invoice_date:p.p_invoice_date??null,supplier_id:p.p_supplier_id??null,related_employee_id:p.p_employee_id??null,department_id:p.p_department_id??null,location_id:item.location_id});return{ok:true,id:tx.id,_operation:{type:"consumable_stock_move",target_id:item.id}};});
export function createMaintenance(s:DemoState,c:OperationContext,input:Row):Row{const a=find(s,"assets",input.asset_id);nonfinancialInput(c,input);const record=createRow(s,"maintenance_records",{type:"corrective",status:"open",workflow_stage:"intake",priority:"medium",problem_type:"hardware",reported_at:now(),started_at:null,completed_at:null,reported_by:c.actor?.userId,reported_by_employee_id:null,technician_id:null,vendor_supplier_id:null,currency:"SAR",cost:null,cost_recorded:false,invoice_number:null,invoice_date:null,action_taken:null,outcome:null,downtime_hours:0,next_due_date:null,final_summary:null,vendor_name:null,vendor_phone:null,vendor_location:null,vendor_map_link:null,handoff_notes:null,receiver_name:null,diagnosis:null,cause_code:null,resolution_code:null,waiting_reason:null,labor_minutes:0,escalation_level:0,escalated_at:null,sla_due_at:new Date(Date.now()+3*86400000).toISOString(),sla_breached_at:null,repair_checklist:{safety_checked:false,function_checked:false,data_checked:false},functional_test_passed:null,functional_test_notes:null,completed_by:null,handoff_state:"pending",...input});assetMovement(s,c,a,{status:"in_maintenance"},"maintenance");return record;}
register(["maintenance_create_atomic"],(s,c,p)=>{operator(c);return{ok:true,id:createMaintenance(s,c,object(p.p_input)).id};});
register(["maintenance_update_safe"],(s,c,p)=>{
  operator(c);const record=find(s,"maintenance_records",p.p_id),input=object(p.p_input);nonfinancialInput(c,input);
  const next={...record,...input},stage=str(next.workflow_stage);
  if(["awaiting_parts","at_vendor"].includes(stage)&&!str(next.waiting_reason).trim())throw new DemoError("23514","maintenance_waiting_reason_required");
  const closing=(input.status==="completed"||stage==="completed")&&record.status!=="completed";
  if(closing){const checklist=object(next.repair_checklist);if(!next.technician_id||!str(next.diagnosis).trim()||!str(next.cause_code).trim()||!str(next.resolution_code).trim()||stage==="completed"&&(next.functional_test_passed!==true||!checklist.safety_checked||!checklist.function_checked||!checklist.data_checked))throw new DemoError("23514","maintenance_completion_evidence_required");}
  const status=input.status??(Object.hasOwn(input,"workflow_stage")?(stage==="completed"?"completed":stage==="intake"?"open":"in_progress"):record.status);
  Object.assign(record,input,{updated_at:now(),cost_recorded:input.cost!=null||record.cost_recorded,status});
  if(closing){Object.assign(record,{completed_at:now(),completed_by:c.actor?.userId,handoff_state:stage==="completed"?"ready_for_custody":"not_ready"});assetMovement(s,c,find(s,"assets",record.asset_id),{status:"available"},"maintenance_complete");}
  return{ok:true};
});
register(["maintenance_assign_technician"],(s,c,p)=>{operator(c);const r=find(s,"maintenance_records",p.p_id);r.technician_id=p.p_technician_id??c.actor?.userId;r.started_at??=now();return{ok:true};});
register(["maintenance_add_time_entry"],(s,c,p)=>{operator(c);const r=find(s,"maintenance_records",p.p_maintenance_id);if(["completed","cancelled"].includes(str(r.status)))throw new DemoError("P0001","invalid_maintenance_state");const minutes=(Date.parse(str(p.p_ended_at))-Date.parse(str(p.p_started_at)))/60000;if(!Number.isFinite(minutes)||minutes<=0)throw new DemoError("22023","invalid_time_range");const entry=createRow(s,"maintenance_time_entries",{maintenance_id:r.id,started_at:p.p_started_at,ended_at:p.p_ended_at,minutes,note:p.p_note??null,technician_id:c.actor?.userId});r.labor_minutes=num(r.labor_minutes)+minutes;return{ok:true,id:entry.id};});
register(["maintenance_plan_part"],(s,c,p)=>{operator(c);const r=find(s,"maintenance_records",p.p_maintenance_id);if(["completed","cancelled"].includes(str(r.status)))throw new DemoError("P0001","invalid_maintenance_state");const qty=num(p.p_planned_quantity,NaN);if(!Number.isFinite(qty)||qty<=0||!p.p_consumable_id&&!str(p.p_description).trim())throw new DemoError("22023","invalid_part");if(p.p_consumable_id)find(s,"consumables",p.p_consumable_id);const entry=createRow(s,"maintenance_parts",{maintenance_id:r.id,consumable_id:p.p_consumable_id??null,description:p.p_description??null,planned_quantity:qty,used_quantity:0,status:"planned"});return{ok:true,id:entry.id};});
register(["maintenance_confirm_handoff"],(s,c,p)=>{operator(c);const r=find(s,"maintenance_records",p.p_id);if(r.status!=="completed"||r.workflow_stage!=="completed"||r.handoff_state!=="ready_for_custody"||r.functional_test_passed!==true)throw new DemoError("P0001","handoff_not_ready");Object.assign(r,{handoff_state:"handed_off",receiver_name:c.actor?.nameAr});return{ok:true};});
register(["import_inventory"],(s,c,p)=>{operator(c);if(!Array.isArray(p.p_items)||p.p_items.length===0)throw new DemoError("22023","empty_import");let assets=0,consumables=0;for(const raw of p.p_items){const input=object(raw);if(input.kind==="consumable"||input.type==="consumable"||input.item_type==="consumable"){const result=operationalRpcs.consumable_create_with_opening_stock.handle(s,c,{p_input:input});if(result)consumables++;}else{createAsset(s,c,input);assets++;}}return{ok:true,assets,consumables,created_assets:assets,created_consumables:consumables,total:assets+consumables};});

function requestItems(s:DemoState,id:unknown):Row[]{return rows(s,"request_items").filter(x=>x.request_id===id);}
function requestAccess(s:DemoState,c:OperationContext,id:unknown,write=false):Row{const actor=requireActor(c);const request=find(s,"requests",id);if(actor.portalRole){portal(c,write);if(request.customer_id!==actor.customerId||(actor.portalRole!=="project_manager"&&actor.portalRole!=="viewer"&&request.submitted_by!==actor.userId))throw new DemoError("42501","not_authorized",403);}else if(actor.role==="employee"&&request.beneficiary_employee_id!==actor.employeeId)throw new DemoError("42501","not_authorized",403);return request;}
export function requestCreate(s:DemoState,c:OperationContext,input:Row,source:"staff"|"portal"|"employee"):Row{const actor=source==="portal"?portal(c,true):requireActor(c);if(source==="staff")operator(c);if(!Array.isArray(input.items)||input.items.length===0)throw new DemoError("22023","items_required");if(source==="portal")input=validatePortalRequestInput(s,c,input,true);if(!Array.isArray(input.items))throw new DemoError("22023","items_required");const rawItems=input.items.map(raw=>source==="portal"?validatePortalItem(s,c,object(raw)):object(raw));for(const it of rawItems)quantity(it.quantity);if(input.pickup_date&&input.return_date&&String(input.return_date)<String(input.pickup_date))throw new DemoError("22023","invalid_date_range");const customerId=source==="portal"?actor.customerId:source==="employee"?null:input.customer_id;if(customerId)find(s,"customers",customerId);const request=createRow(s,"requests",{request_number:`REQ-${new Date().getFullYear()}-${String(rows(s,"requests").length+1).padStart(4,"0")}`,customer_id:customerId??null,customer_name_snapshot:customerId?find(s,"customers",customerId).name:null,contact_phone_snapshot:input.contact_phone??input.contact_phone_snapshot??input.contact_phone??null,contact_phone:input.contact_phone??null,contact_email:input.contact_email??null,contact_email_snapshot:input.contact_email??null,project_name:input.project_name??null,project_city:input.project_city??null,request_type:source==="employee"?"internal":input.request_type??"rental",beneficiary_type:source==="employee"?"employee":"customer",beneficiary_employee_id:source==="employee"?actor.employeeId:null,status:source==="portal"?"draft":input.status??"under_review",request_source:source==="portal"?"client_portal":"internal",portal_approval_status:"not_required",submitted_by:actor.userId,created_by:actor.userId,approved_by:null,responsible_employee_id:null,pickup_date:input.pickup_date??null,return_date:input.return_date??null,delivered_at:null,returned_at:null,approved_at:null,rejected_at:null,rejection_reason:null,prepared_by:null,prepared_at:null,second_approved_by:null,second_approved_at:null,delivered_by:null,delivery_proof_id:null,risk_level_snapshot:null,risk_reason_snapshot:null,notes:input.notes??null,internal_notes:source==="staff"?input.internal_notes??null:null,creation_complete:true});for(const it of rawItems)requestAddItem(s,request,it);addEvent(s,c,"request_events",{request_id:request.id,event_type:"created",to_status:request.status,message:"تم إنشاء الطلب",metadata:{}});return request;}
function requestAddItem(s:DemoState,request:Row,input:Row):Row{const kind=input.item_kind??(input.requested_kind==="consumable"?"consumable":"custom");if(input.consumable_id)find(s,"consumables",input.consumable_id);if(input.asset_id)find(s,"assets",input.asset_id);return createRow(s,"request_items",{request_id:request.id,item_kind:kind,asset_id:null,consumable_id:null,quantity:quantity(input.quantity),approved_quantity:null,delivered_quantity:0,returned_quantity:0,unit_price:null,total_price:null,notes:null,requested_kind:kind==="consumable"?"consumable":"existing_asset",requested_description:null,requested_category:null,preferred_model:null,preferred_company_id:null,accept_alternative:true,needs_purchase:false,...input});}
register(["request_create_idempotent"],(s,c,p)=>{const actor=requireActor(c);return{ok:true,id:requestCreate(s,c,object(p.p_input),actor.role==="employee"?"employee":"staff").id};});
register(["request_create_employee_self"],(s,c,p)=>{const actor=staff(c);if(!actor.employeeId)throw new DemoError("P0001","employee_required");return{ok:true,id:requestCreate(s,c,{...p,project_name:p.p_project_name,pickup_date:p.p_pickup_date,return_date:p.p_return_date,notes:p.p_notes,status:p.p_status,items:p.p_items},"employee").id};});
