register(["portal_create_request"],(s,c,p)=>{portal(c,true);const input:Row={};for(const[k,v]of Object.entries(p))input[k.replace(/^p_/,"")]=v;input.items=[{quantity:1,requested_kind:"custom",requested_description:"أضف بند الطلب"}];const r=requestCreate(s,c,input,"portal");s.tables.request_items=requestItems(s,r.id).length?s.tables.request_items.filter(x=>x.request_id!==r.id):s.tables.request_items;r.creation_complete=false;return{ok:true,id:r.id};});
register(["portal_add_item"],(s,c,p)=>{const r=requestAccess(s,c,p.p_request_id,true);if(r.status!=="draft")throw new DemoError("P0001","request_not_draft");const input:Row={};for(const[k,v]of Object.entries(p))input[k.replace(/^p_/,"")]=v;delete input.request_id;const item=requestAddItem(s,r,validatePortalItem(s,c,input));return{ok:true,id:item.id};});
register(["portal_remove_item"],(s,c,p)=>{const item=find(s,"request_items",p.p_item_id);const r=requestAccess(s,c,item.request_id,true);if(r.status!=="draft")throw new DemoError("P0001","request_not_draft");s.tables.request_items=s.tables.request_items.filter(x=>x.id!==item.id);return{ok:true};});
function transition(s:DemoState,c:OperationContext,r:Row,to:string,event:string,message:unknown=null):void{const from=r.status;r.status=to;r.updated_at=now();addEvent(s,c,"request_events",{request_id:r.id,event_type:event,to_status:to,message,metadata:{}});if(from!==to)addEvent(s,c,"request_events",{request_id:r.id,event_type:"status_changed",to_status:to,message:null,metadata:{from,to}});}
register(["portal_submit_request"],(s,c,p)=>{const actor=portal(c,true),r=requestAccess(s,c,p.p_request_id,true);validatePortalSubmission(s,c,r);const config=resolveDemoPortalSettings(s,r.customer_id);const pending=config?.require_project_manager_approval===true&&actor.portalRole==="authorized_requester";if(pending){Object.assign(r,{portal_approval_status:"pending_project_manager",portal_approval_requested_by:actor.userId,portal_approval_requested_at:now()});addEvent(s,c,"request_events",{request_id:r.id,event_type:"portal_pm_approval_requested",message:null,metadata:{availability_snapshot:true}});}else{if(actor.portalRole==="project_manager"&&config?.require_project_manager_approval===true)Object.assign(r,{portal_approval_status:"approved_by_project_manager",portal_approved_by:actor.userId,portal_approved_at:now()});transition(s,c,r,"under_review","submitted");}return{ok:true,pending_pm:pending};});
register(["portal_pm_approve_request","portal_pm_reject_request"],(s,c,p)=>{const actor=portal(c,true);if(actor.portalRole!=="project_manager")throw new DemoError("42501","not_authorized",403);const r=requestAccess(s,c,p.p_request_id,true);if(r.status!=="draft"||r.portal_approval_status!=="pending_project_manager")throw new DemoError("P0001","invalid_state");const reject=Object.hasOwn(p,"p_reason");r.portal_approval_status=reject?"rejected_by_project_manager":"approved_by_project_manager";if(reject)Object.assign(r,{portal_rejection_reason:str(p.p_reason).trim()||null,portal_rejected_by:actor.userId,portal_rejected_at:now()});else Object.assign(r,{portal_approved_by:actor.userId,portal_approved_at:now()});transition(s,c,r,reject?"cancelled":"under_review",reject?"portal_pm_rejected":"portal_pm_approved",reject?str(p.p_reason).trim()||null:null);if(!reject)addEvent(s,c,"request_events",{request_id:r.id,event_type:"submitted",message:null,metadata:{}});return{ok:true};});
register(["portal_reply_clarification","employee_reply_request_clarification"],(s,c,p)=>{const r=requestAccess(s,c,p.p_request_id,true);if(r.status!=="needs_clarification"||!str(p.p_message).trim())throw new DemoError("P0001","invalid_clarification");transition(s,c,r,"under_review","clarification_reply",p.p_message);return{ok:true};});
function releaseItems(s:DemoState,c:OperationContext,r:Row):void{for(const item of requestItems(s,r.id)){if(item.asset_id){const a=find(s,"assets",item.asset_id);if(!a.assigned_to_employee_id)assetMovement(s,c,a,{status:"available"},"request_release");}item.asset_id=null;if(item.item_kind==="asset")item.item_kind="custom";}}
const transitionRules:Record<string,{from:string[];to:string;manager?:boolean}>={submit:{from:["draft"],to:"under_review"},approve:{from:["under_review"],to:"approved",manager:true},reject:{from:["under_review","needs_clarification","approved"],to:"rejected",manager:true},start_preparing:{from:["approved","provisioned"],to:"preparing"},mark_ready:{from:["preparing"],to:"ready_for_pickup"},confirm_ready:{from:["approved","provisioned","preparing"],to:"ready_for_pickup"},return:{from:["delivered","overdue","partially_returned"],to:"returned"},inspect_return:{from:["delivered","overdue","partially_returned"],to:"returned"},complete:{from:["returned","delivered","partially_returned"],to:"completed"},cancel:{from:["draft","under_review","needs_clarification","approved","provisioned","stock_shortage","preparing","ready_for_pickup"],to:"cancelled"}};
register(["request_execute_idempotent"],(s,c,p)=>{const actor=requireActor(c);const op=str(p.p_operation_type);const rule=transitionRules[op];if(!rule)throw new DemoError("22023","invalid_operation_type");const r=requestAccess(s,c,p.p_request_id);if(rule.manager)manager(c);else if(actor.role==="employee"){if(!["submit","cancel"].includes(op))throw new DemoError("42501","not_authorized",403);}else operator(c);if(!rule.from.includes(str(r.status)))throw new DemoError("P0001","invalid_request_transition");const payload=p.p_payload?object(p.p_payload):{};if(op==="reject"&&!str(payload.reason).trim())throw new DemoError("22023","reason_required");if(["mark_ready","confirm_ready"].includes(op)&&requestItems(s,r.id).some(x=>x.item_kind==="custom"&&!x.asset_id))throw new DemoError("P0001","unfulfilled_items");if(op==="approve"){if(r.portal_approval_status==="pending_project_manager")throw new DemoError("P0001","pm_approval_required");r.approved_at=now();r.approved_by=actor.userId;}if(op==="reject"){r.rejected_at=now();r.rejection_reason=payload.reason;}if(op==="start_preparing"||["mark_ready","confirm_ready"].includes(op)&&!r.prepared_by){r.prepared_by=actor.userId;r.prepared_at=now();}if(op==="cancel"||op==="reject")releaseItems(s,c,r);if(op==="return"){if(requestItems(s,r.id).some(it=>it.asset_id&&num(it.delivered_quantity)>num(it.returned_quantity)))throw new DemoError("P0001","inspection_required");r.returned_at=now();}
  if(op==="inspect_return"){
    if(!Array.isArray(payload.lines)||payload.lines.length===0)throw new DemoError("22023","invalid_return_inspection");
    const seen=new Set<unknown>();
    for(const raw of payload.lines){const line=object(raw),item=requestItems(s,r.id).find(it=>it.asset_id===line.asset_id&&num(it.delivered_quantity)>num(it.returned_quantity));if(!item||seen.has(line.asset_id)||!["sound","needs_inspection"].includes(str(line.condition))||line.condition==="needs_inspection"&&!str(line.notes).trim())throw new DemoError("22023","invalid_return_inspection");seen.add(line.asset_id);}
    for(const raw of payload.lines){const line=object(raw),item=requestItems(s,r.id).find(it=>it.asset_id===line.asset_id)!,a=find(s,"assets",line.asset_id);assetMovement(s,c,a,{status:"available",assigned_to_employee_id:null,last_return_at:now(),last_return_condition:line.condition==="sound"?"sound":"needs_maintenance"},"request_return",line.notes);for(const assignment of rows(s,"asset_assignments").filter(x=>x.asset_id===a.id&&x.status==="active"))Object.assign(assignment,{status:"returned",returned_at:now(),return_condition:line.condition==="sound"?"good":"fair"});item.returned_quantity=item.delivered_quantity;if(line.condition==="needs_inspection")createMaintenance(s,c,{asset_id:a.id,problem_description:line.notes});}
    const remaining=requestItems(s,r.id).some(it=>it.asset_id&&num(it.delivered_quantity)>num(it.returned_quantity));if(remaining){transition(s,c,r,"partially_returned","inspected_return");return{ok:true,id:r.id};}r.returned_at=now();
  }
  if(op==="complete"&&r.request_type!=="sale"&&requestItems(s,r.id).some(it=>{if(!it.asset_id||num(it.delivered_quantity)===0)return false;const a=find(s,"assets",it.asset_id);return a.last_request_id!==r.id||!a.last_out_at||!a.last_return_at||str(a.last_return_at)<str(a.last_out_at)||!["sound","unsound","missing","needs_maintenance"].includes(str(a.last_return_condition));}))throw new DemoError("P0001","inspection_required");
  transition(s,c,r,rule.to,op,payload.reason);return{ok:true,id:r.id,_operation:{type:op,target_id:r.id}};});
function allocate(s:DemoState,c:OperationContext,item:Row,asset:Row):void{if(asset.status!=="available"||asset.assigned_to_employee_id)throw new DemoError("P0001","asset_not_available");if(item.asset_id)throw new DemoError("P0001","item_already_allocated");Object.assign(item,{asset_id:asset.id,item_kind:"asset",approved_quantity:1,quantity:1});assetMovement(s,c,asset,{status:"reserved",last_request_id:item.request_id},"request_reserve");}
