register(["request_auto_provision"],(s,c,p)=>{operator(c);const r=requestAccess(s,c,p.p_id);if(!["approved","stock_shortage"].includes(str(r.status)))throw new DemoError("P0001","invalid_request_transition");let shortage=false;for(const it of [...requestItems(s,r.id)]){if(it.asset_id)continue;if(it.item_kind==="consumable"){if(num(find(s,"consumables",it.consumable_id).quantity_on_hand)<num(it.quantity))shortage=true;continue;}const candidates=rows(s,"assets").filter(a=>a.status==="available"&&!a.assigned_to_employee_id&&(!it.model_id||a.model_id===it.model_id)&&(!it.category_id||a.category_id===it.category_id)&&(!it.preferred_company_id||a.company_id===it.preferred_company_id));const qty=num(it.quantity);if(candidates.length<qty){shortage=true;it.needs_purchase=true;continue;}allocate(s,c,it,candidates[0]);for(let i=1;i<qty;i++){const extra=requestAddItem(s,r,{...it,id:uid(),asset_id:null,quantity:1});allocate(s,c,extra,candidates[i]);}}transition(s,c,r,shortage?"stock_shortage":"provisioned","auto_provisioned");return{ok:true,shortage};});
register(["request_shortage_fulfill_available"],(s,c,p)=>{operator(c);const r=requestAccess(s,c,p.p_id);if(r.status!=="stock_shortage")throw new DemoError("P0001","invalid_request_transition");s.tables.request_items=s.tables.request_items.filter(it=>it.request_id!==r.id||it.asset_id||it.item_kind==="consumable");if(!requestItems(s,r.id).length)throw new DemoError("P0001","no_available_items");transition(s,c,r,"provisioned","shortage_available_only");return{ok:true};});
register(["request_item_fulfill"],(s,c,p)=>{operator(c);const it=find(s,"request_items",p.p_item_id);requestAccess(s,c,it.request_id);if(Boolean(p.p_asset_id)===Boolean(p.p_consumable_id))throw new DemoError("22023","one_reference_required");if(p.p_asset_id)allocate(s,c,it,find(s,"assets",p.p_asset_id));else{const consumable=find(s,"consumables",p.p_consumable_id);Object.assign(it,{consumable_id:consumable.id,item_kind:"consumable"});}return{ok:true};});
