register(["request_secondary_approve"],(s,c,p)=>{const actor=staff(c),r=requestAccess(s,c,p.p_id);if(!p.p_operation_id||str(p.p_reason).trim().length<3)throw new DemoError("22023","reason_required");if(!["approved","provisioned","preparing","ready_for_pickup"].includes(str(r.status))||!r.approved_by)throw new DemoError("22023","invalid_state");const risk=demoRequestRisk(s,r.id);if(risk.level!=="high")throw new DemoError("22023","second_approval_not_required");if([r.created_by,r.approved_by,r.prepared_by].includes(actor.userId))throw new DemoError("42501","independent_approver_required",403);if(r.second_approved_by!=null)throw new DemoError("42501","invalid_secondary_approval",403);Object.assign(r,{second_approved_by:actor.userId,second_approved_at:now(),second_approval_reason:str(p.p_reason).trim(),risk_level_snapshot:risk.level,risk_reason_snapshot:risk.reason});return{ok:true,risk_level:risk.level};});
register(["request_deliver_with_proof"],(s,c,p)=>{operator(c);const r=requestAccess(s,c,p.p_id);if(r.status!=="ready_for_pickup")throw new DemoError("P0001","invalid_request_transition");const proof=object(p.p_proof);if(proof.acknowledged!==true||str(proof.receiver_name).trim().length<2||str(proof.receiver_name).trim().length>160||str(proof.delivery_notes).trim().length>1000)throw new DemoError("22023","invalid_delivery_proof");const assetIds=requestItems(s,r.id).filter(it=>it.asset_id).map(it=>it.asset_id);if(!Array.isArray(proof.verified_asset_ids)||proof.verified_asset_ids.length!==assetIds.length||new Set(proof.verified_asset_ids).size!==assetIds.length||assetIds.some(id=>!proof.verified_asset_ids || !(proof.verified_asset_ids as unknown[]).includes(id)))throw new DemoError("P0001","device_verification_required");const risk=demoRequestRisk(s,r.id);if(risk.level==="high"){if(!r.second_approved_by)throw new DemoError("42501","second_approval_required",403);if(!r.prepared_by)throw new DemoError("42501","preparer_evidence_required",403);if([r.created_by,r.approved_by,r.second_approved_by,r.prepared_by].includes(c.actor?.userId))throw new DemoError("42501","independent_deliverer_required",403);throw new DemoError("22023","strong_proof_required");}for(const it of requestItems(s,r.id)){if(it.item_kind==="custom")throw new DemoError("P0001","unfulfilled_items");if(it.consumable_id){const item=find(s,"consumables",it.consumable_id);const qty=num(it.quantity);if(num(item.quantity_on_hand)<qty)throw new DemoError("P0001","insufficient_stock");const prev=num(item.quantity_on_hand);item.quantity_on_hand=prev-qty;createRow(s,"consumable_transactions",{consumable_id:item.id,txn_type:"out",quantity:qty,previous_quantity:prev,balance_after:item.quantity_on_hand,reason:`Request ${r.request_number}`,performed_by:c.actor?.userId,unit_cost:null,total_cost:null});}it.delivered_quantity=it.quantity;if(it.asset_id){const a=find(s,"assets",it.asset_id);const target="reserved";if(r.beneficiary_type==="employee"){const employee=find(s,"employees",r.beneficiary_employee_id);if(employee.is_active!==true)throw new DemoError("P0001","beneficiary_inactive");createRow(s,"asset_assignments",{asset_id:a.id,employee_id:r.beneficiary_employee_id,assigned_by:c.actor?.userId,assigned_at:now(),due_return_date:r.return_date,status:"active",returned_at:null});a.assigned_to_employee_id=r.beneficiary_employee_id;}assetMovement(s,c,a,{status:target,...(r.request_type==="sale"?{archived_at:a.archived_at??now(),is_active:false}:{}),times_checked_out:num(a.times_checked_out)+1,last_out_at:now(),last_request_id:r.id},r.beneficiary_type==="employee"?"assign":"status_change");}}const evidence=createRow(s,"request_delivery_proofs",{request_id:r.id,receiver_name:proof.receiver_name,delivery_notes:proof.delivery_notes??null,method:"acknowledgement",delivered_by:c.actor?.userId,acknowledged_at:now(),device_snapshot:assetIds.map(id=>{const a=find(s,"assets",id);return{asset_id:a.id,asset_tag:a.asset_tag,name:a.name};})});Object.assign(r,{delivered_at:now(),delivered_by:c.actor?.userId,delivery_proof_id:evidence.id,risk_level_snapshot:risk.level,risk_reason_snapshot:risk.reason});transition(s,c,r,r.request_type==="sale"?"completed":"delivered","delivered");return{ok:true,id:r.id,_operation:{type:"deliver",target_id:r.id}};});
