function stocktakeAccess(s:DemoState,c:OperationContext,id:unknown):Row{operator(c);return find(s,"stocktakes",id);}
function stockItems(s:DemoState,id:unknown):Row[]{return rows(s,"stocktake_items").filter(i=>i.stocktake_id===id);}
function updateCounts(s:DemoState,session:Row):void{const items=stockItems(s,session.id);session.expected_count=items.filter(i=>i.is_expected).length;session.observed_count=items.filter(i=>i.scanned).length;session.variance_count=items.filter(i=>i.classification&&i.classification!=="found").length;}
register(["stocktake_create"],(s,c,p)=>{operator(c);find(s,"locations",p.p_location_id);if(!str(p.p_title).trim())throw new DemoError("22023","title_required");if(p.p_scope_kind==="partial"&&!p.p_scope_category_id)throw new DemoError("22023","category_required");const session=createRow(s,"stocktakes",{code:`ST-${new Date().getFullYear()}-${String(rows(s,"stocktakes").length+1).padStart(3,"0")}`,title:p.p_title,location_id:p.p_location_id,status:"draft",review_state:"counting",snapshot_at:now(),started_at:null,submitted_at:null,completed_at:null,expected_count:0,observed_count:0,variance_count:0,blind_count:true,correction_of:p.p_correction_of??null,created_by:c.actor?.userId,reviewed_by:null,scope_kind:p.p_scope_kind??"full",scope_category_id:p.p_scope_category_id??null});for(const a of rows(s,"assets").filter(a=>a.location_id===p.p_location_id&&(!p.p_scope_category_id||a.category_id===p.p_scope_category_id)&&a.is_active))createRow(s,"stocktake_items",{stocktake_id:session.id,asset_id:a.id,asset_tag:a.asset_tag,asset_name:a.name,is_expected:true,scanned:false,observation_status:null,classification:null,count_round:1,recount_required:false,variance_reason:null,adjustment_applied:false,observed_at:null,review_decision:null,review_note:null});updateCounts(s,session);addEvent(s,c,"stocktake_events",{stocktake_id:session.id,event_type:"created",reason:null,item_id:null});return{ok:true,id:session.id,code:session.code};});
register(["stocktake_start"],(s,c,p)=>{const session=stocktakeAccess(s,c,p.p_stocktake_id);if(session.status!=="draft")throw new DemoError("P0001","invalid_stocktake_state");Object.assign(session,{status:"in_progress",started_at:now()});addEvent(s,c,"stocktake_events",{stocktake_id:session.id,event_type:"started",reason:null,item_id:null});return{ok:true};});
register(["stocktake_scan"],(s,c,p)=>{const session=stocktakeAccess(s,c,p.p_stocktake_id);if(session.status!=="in_progress"||!["counting","recount"].includes(str(session.review_state)))throw new DemoError("P0001","stocktake_not_counting");const identifier=str(p.p_identifier).trim().split("/a/").pop();const a=rows(s,"assets").find(a=>[a.asset_tag,a.qr_token,a.serial_number,a.rfid_tag].includes(identifier));if(!a)throw new DemoError("P0002","asset_not_found",404);let item=stockItems(s,session.id).find(x=>x.asset_id===a.id);if(!item)item=createRow(s,"stocktake_items",{stocktake_id:session.id,asset_id:a.id,asset_tag:a.asset_tag,asset_name:a.name,is_expected:false,scanned:false,count_round:1,recount_required:false,variance_reason:null,adjustment_applied:false,review_decision:null,review_note:null});const classification=item.is_expected?(a.location_id===session.location_id?"found":"wrong_location"):"unexpected";Object.assign(item,{scanned:true,classification,observation_status:classification,observed_at:now(),recount_required:false});updateCounts(s,session);addEvent(s,c,"stocktake_events",{stocktake_id:session.id,item_id:item.id,event_type:"scanned",reason:null});return{ok:true,item_id:item.id,classification,count_round:item.count_round};});
