register(["stocktake_decide_item"],(s,c,p)=>{const actor=manager(c),session=find(s,"stocktakes",p.p_stocktake_id),item=find(s,"stocktake_items",p.p_item_id);if(!["approve_correction","keep_current","request_recheck"].includes(str(p.p_decision))||str(p.p_note).trim().length<3||str(p.p_note).length>1000)throw new DemoError("22023","invalid_discrepancy_decision");if(session.status!=="in_progress"||session.review_state!=="submitted")throw new DemoError("22023","stocktake_not_reviewable");if(item.stocktake_id!==session.id||!["missing","unexpected","wrong_location"].includes(str(item.observation_status??item.classification)))throw new DemoError("22023","variance_item_required");if(item.review_decision!=null)throw new DemoError("22023","discrepancy_already_decided");Object.assign(item,{review_decision:p.p_decision,review_note:str(p.p_note).trim(),decided_by:actor.userId,decided_at:now()});if(p.p_decision==="request_recheck"){Object.assign(item,{recount_required:true,scanned:false,found:false,classification:null,observation_status:null,observed_at:null,count_round:num(item.count_round)+1});session.review_state="recount";updateCounts(s,session);}addEvent(s,c,"stocktake_events",{stocktake_id:session.id,item_id:item.id,event_type:"discrepancy_decided",reason:p.p_note,metadata:{decision:p.p_decision}});return{ok:true,item_id:item.id,decision:p.p_decision};});
register(["stocktake_review"],(s,c,p)=>{const actor=manager(c),session=find(s,"stocktakes",p.p_stocktake_id);if(p.p_decision!=="rejected"||str(p.p_reason).trim().length<3)throw new DemoError("22023","invalid_review");if(session.status!=="in_progress"||session.review_state!=="submitted")throw new DemoError("22023","stocktake_not_reviewable");Object.assign(session,{review_state:"rejected",reviewed_by:actor.userId,reviewed_at:now()});addEvent(s,c,"stocktake_events",{stocktake_id:session.id,event_type:"reviewed",reason:p.p_reason,item_id:null});return{ok:true,id:session.id,decision:"rejected"};});
register(["stocktake_apply_adjustments"],(s,c,p)=>{const actor=manager(c),session=find(s,"stocktakes",p.p_stocktake_id);if(session.status!=="in_progress"||session.review_state!=="submitted")throw new DemoError("22023","submitted_stocktake_required");const items=stockItems(s,session.id);if(items.some(i=>["missing","unexpected","wrong_location"].includes(str(i.observation_status??i.classification))&&i.review_decision==null))throw new DemoError("22023","every_discrepancy_requires_decision");if(items.some(i=>i.review_decision==="request_recheck"))throw new DemoError("22023","recheck_required");let count=0;for(const item of items){if(item.review_decision==="approve_correction"&&!item.adjustment_applied&&["wrong_location","unexpected"].includes(str(item.observation_status??item.classification))){const a=find(s,"assets",item.asset_id);if(a.location_id!==session.location_id){assetMovement(s,c,a,{location_id:session.location_id},"transfer",`Stocktake ${session.code}: ${item.review_note}`);count++;}item.adjustment_applied=true;}}Object.assign(session,{status:"completed",review_state:"approved",reviewed_by:actor.userId,reviewed_at:now(),completed_at:now(),locked_at:now()});addEvent(s,c,"stocktake_events",{stocktake_id:session.id,event_type:"completed",metadata:{adjustments_applied:count}});return{ok:true,id:session.id,adjustments_applied:count};});

register(["purchase_requests_create_from_shortages"],(s,c,p)=>{operator(c);if(!Array.isArray(p.p_items)||p.p_items.length===0)throw new DemoError("22023","items_required");const groups=new Map<string,Row[]>();for(const raw of p.p_items){const it=object(raw);find(s,"consumables",it.consumable_id);quantity(it.quantity);const key=str(it.supplier_id);groups.set(key,[...(groups.get(key)??[]),it]);}const numbers:string[]=[];for(const [supplier,items]of groups){const pr=createRow(s,"purchase_requests",{request_number:`PR-${new Date().getFullYear()}-${String(rows(s,"purchase_requests").length+1).padStart(4,"0")}`,supplier_id:supplier||null,status:"draft",requested_by:c.actor?.userId,notes:null});for(const it of items)createRow(s,"purchase_request_items",{purchase_request_id:pr.id,pr_id:pr.id,consumable_id:it.consumable_id,description:null,requested_quantity:it.quantity,quantity:it.quantity,suggested_quantity:it.quantity,received_quantity:0,notes:null,unit_cost:null});numbers.push(str(pr.request_number));}return{ok:true,numbers};});
register(["purchase_request_set_status"],(s,c,p)=>{operator(c);const pr=find(s,"purchase_requests",p.p_id);const to=str(p.p_to);if(to==="cancelled"&&!financial(c)&&!(pr.status==="draft"&&pr.requested_by===c.actor?.userId))throw new DemoError("42501","bad_transition",403);if(["approved","second_approved"].includes(to))manager(c);if(to==="approved"&&pr.requested_by===c.actor?.userId)throw new DemoError("42501","independent_approver_required",403);if(to==="second_approved"){if(pr.status!=="approved")throw new DemoError("P0001","invalid_purchase_request_transition");if([pr.requested_by,pr.approved_by].includes(c.actor?.userId))throw new DemoError("42501","second_approver_must_differ",403);pr.second_approved_by=c.actor?.userId;pr.second_approved_at=now();return{ok:true};}if(to==="ordered"){if(!pr.second_approved_by)throw new DemoError("42501","second_approval_required",403);if([pr.requested_by,pr.approved_by,pr.second_approved_by].includes(c.actor?.userId))throw new DemoError("42501","independent_orderer_required",403);}if(to==="submitted"&&!rows(s,"purchase_request_items").some(i=>i.purchase_request_id===pr.id))throw new DemoError("22023","items_required");const allowed:Record<string,string[]>={draft:["submitted","cancelled"],submitted:["approved","cancelled"],approved:["ordered","cancelled"],ordered:["cancelled"]};if(!allowed[str(pr.status)]?.includes(to))throw new DemoError("P0001","invalid_purchase_request_transition");pr.status=to;pr.updated_at=now();if(to==="submitted")pr.submitted_at=now();if(to==="approved"){pr.approved_at=now();pr.approved_by=c.actor?.userId;}if(to==="cancelled")pr.cancelled_at=now();return{ok:true};});
register(["purchase_request_item_receive_idempotent"],(s,c,p)=>{operator(c);const item=find(s,"purchase_request_items",p.p_item_id);const pr=find(s,"purchase_requests",item.purchase_request_id);if(!["ordered","partially_received"].includes(str(pr.status)))throw new DemoError("P0001","purchase_request_not_ordered");if(!pr.second_approved_by)throw new DemoError("42501","second_approval_required",403);if([pr.requested_by,pr.approved_by,pr.second_approved_by].includes(c.actor?.userId))throw new DemoError("42501","independent_receiver_required",403);const qty=quantity(p.p_qty);if(num(item.received_quantity)+qty>num(item.requested_quantity))throw new DemoError("P0001","receipt_exceeds_requested");item.received_quantity=num(item.received_quantity)+qty;const items=rows(s,"purchase_request_items").filter(it=>it.purchase_request_id===pr.id);pr.status=items.every(it=>num(it.received_quantity)>=num(it.requested_quantity))?"received":"partially_received";return{ok:true,_operation:{type:"purchase_receipt",target_id:item.id}};});
register(["request_item_convert_to_pr"],(s,c,p)=>{manager(c);const it=find(s,"request_items",p.p_item_id);let pr=p.p_pr_id?find(s,"purchase_requests",p.p_pr_id):createRow(s,"purchase_requests",{request_number:`PR-${new Date().getFullYear()}-${String(rows(s,"purchase_requests").length+1).padStart(4,"0")}`,status:"draft",requested_by:c.actor?.userId,supplier_id:null,notes:null});if(pr.status!=="draft")throw new DemoError("P0001","purchase_request_not_draft");createRow(s,"purchase_request_items",{purchase_request_id:pr.id,pr_id:pr.id,request_item_id:it.id,description:it.requested_description,consumable_id:it.consumable_id,requested_quantity:it.quantity,quantity:it.quantity,received_quantity:0,suggested_quantity:it.quantity,unit_cost:null,notes:null});it.needs_purchase=true;return{ok:true,id:pr.id};});
register(["procurement_record_external_document"],(s,c,p)=>{operator(c);const pr=find(s,"purchase_requests",p.p_purchase_request_id);const type=str(p.p_document_type);if(!["purchase_order","goods_receipt","invoice","stock_receipt"].includes(type)||!str(p.p_external_reference).trim()||!str(p.p_source_system).trim())throw new DemoError("22023","invalid_document");if(type==="invoice")manager(c);if(p.p_purchase_request_item_id){const it=find(s,"purchase_request_items",p.p_purchase_request_item_id);if(it.purchase_request_id!==pr.id)throw new DemoError("22023","item_request_mismatch");}if(type==="stock_receipt"){const tx=find(s,"consumable_transactions",p.p_stock_transaction_id);const it=find(s,"purchase_request_items",p.p_purchase_request_item_id);if(tx.txn_type!=="in"||tx.consumable_id!==it.consumable_id)throw new DemoError("22023","stock_receipt_mismatch");}if(rows(s,"procurement_documents").some(d=>d.source_system===p.p_source_system&&d.external_reference===p.p_external_reference&&d.document_type===type))throw new DemoError("23505","duplicate_document_reference");const doc=createRow(s,"procurement_documents",{purchase_request_id:pr.id,pr_id:pr.id,purchase_request_item_id:p.p_purchase_request_item_id??null,document_type:type,source_system:p.p_source_system,external_reference:p.p_external_reference,document_status:p.p_document_status??"recorded",stock_transaction_id:p.p_stock_transaction_id??null,metadata:p.p_metadata??{},recorded_by:c.actor?.userId});return{ok:true,id:doc.id};});
